import * as React from "react";
import { graphql, type HeadFC, type PageProps } from "gatsby";
import {
  ProblemLandingHeadProvider,
  ProblemLandingPage,
} from "../components/ProblemLandingPage";

const WebsiteRedesignServiceBusinessesPage: React.FC<PageProps> = () => (
  <ProblemLandingPage landingKey="websiteRedesignServiceBusinesses" />
);

export const Head: HeadFC = ({ data, pageContext }) => (
  <ProblemLandingHeadProvider
    landingKey="websiteRedesignServiceBusinesses"
    data={data}
    pageContext={pageContext}
  />
);

export default WebsiteRedesignServiceBusinessesPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
